-- Hyprland Lua config, converted from hyprland.conf
-- Reference: https://wiki.hypr.land/0.56.0/Configuring/Start/


-----------------
---- COLORS -----
-----------------

-- Generated by matugen (template "hyprland_lua" -> ~/.config/hypr/colors.lua).
-- pcall so a missing colors file doesn't abort the whole config
-- (see "Require" on the Start wiki page).
local ok, colors = pcall(require, "colors")
if not ok then
  colors = { primary = "rgb(1E3F33)" }
end


------------------
---- MONITORS ----
------------------

hl.monitor({
  output   = "",
  mode     = "highres",
  position = "auto-left",
  scale    = 1,
})


-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

hl.env("XCURSOR_THEME", "")
hl.env("XCURSOR_SIZE", "16")
hl.env("HYPRCURSOR_THEME", "")
hl.env("HYPRCURSOR_SIZE", "16")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")


---------------------
---- MY PROGRAMS ----
---------------------

local terminal    = "kitty"
local fileManager = "nautilus"
local menu        = "rofi -show drun"
local browser     = "firefox"


-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
  hl.exec_cmd("systemctl --user start hyprpolkitagent")
  hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme \"prefer-dark\"")
  hl.exec_cmd("awww-daemon & sleep 0.5 && awww clear")
  hl.exec_cmd("wl-paste --type text --watch cliphist store")
  hl.exec_cmd("wl-paste --type image --watch cliphist store")
  hl.exec_cmd("bash ~/.config/scripts/media.sh")
  hl.exec_cmd("waybar")
  hl.exec_cmd("fcitx5 -d")
end)


-----------------------
---- LOOK AND FEEL ----
-----------------------

hl.config({
  general = {
    gaps_in     = 5,  -- @dynamic_gaps_in
    gaps_out    = 10, -- @dynamic_gaps_out
    border_size = 2,  -- @dynamic_border

    col = {
      active_border = colors.primary,
    },

    resize_on_border = false,
    allow_tearing    = false,

    layout = "dwindle",
  },

  decoration = {
    rounding       = 0,
    rounding_power = 0,

    active_opacity   = 1.0,
    inactive_opacity = 1.0,

    shadow = {
      enabled      = true,
      range        = 4,
      render_power = 3,
      color        = "rgba(1a1a1aee)",
    },

    blur = {
      enabled  = true,
      size     = 3,
      passes   = 1,
      vibrancy = 0.1696,
    },
  },

  animations = {
    enabled = true,
  },

  dwindle = {
    preserve_split = true,
  },

  misc = {
    force_default_wallpaper    = 0,
    disable_hyprland_logo      = true,
    disable_splash_rendering   = true,
    initial_workspace_tracking = 1,
  },
})


--------------------
---- ANIMATIONS ----
--------------------

hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}   } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}   } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}      } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}   } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}    } })
hl.curve("hard",           { type = "bezier", points = { {0, 1},       {0, 1}      } })

hl.animation({ leaf = "global",           enabled = true, speed = 5,    bezier = "default" })
hl.animation({ leaf = "border",           enabled = true, speed = 2.5,  bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",          enabled = true, speed = 2.5,  bezier = "easeOutQuint" })
hl.animation({ leaf = "windowsIn",        enabled = true, speed = 2,    bezier = "easeOutQuint", style = "popin 87%" })
hl.animation({ leaf = "windowsOut",       enabled = true, speed = 1,    bezier = "linear",       style = "popin 87%" })
hl.animation({ leaf = "fadeIn",           enabled = true, speed = 1,    bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut",          enabled = true, speed = 1,    bezier = "almostLinear" })
hl.animation({ leaf = "fade",             enabled = true, speed = 1.5,  bezier = "quick" })
hl.animation({ leaf = "layers",           enabled = true, speed = 2,    bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",         enabled = true, speed = 2,    bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut",        enabled = true, speed = 1,    bezier = "linear",       style = "fade" })
hl.animation({ leaf = "workspaces",       enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" }) -- @dynamic_workspaces
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" }) -- @dynamic_special


