----------------------
---- WINDOW RULES ----
----------------------

hl.window_rule({
  name   = "floating-window-tag",
  match  = { tag = "floating-window" },
  float  = true,
  center = true,
  size   = { 800, 600 },
})

-- File pickers / save dialogs get the floating-window tag
hl.window_rule({
  name  = "tag-file-dialogs",
  match = {
    class = "^(local\\.xdg-desktop-portal-gtk|local\\.sublime_text|local\\.DesktopEditors|local\\.org\\.gnome\\.Nautilus)$",
    title = "^(Open.*Files?|Open [Ff]older.*|Save.*Files?|Save.*As|Save|All Files)$",
  },
  tag   = "+floating-window",
})

-- CLI tools
hl.window_rule({
  name   = "cli-tools-float",
  match  = { class = "^(local\\.bluetui|local\\.impala|local\\.wiremix|local\\.org\\.gnome\\.NautilusPreviewer|local\\.com\\.gabm\\.satty)$" },
  float  = true,
  center = true,
  size   = { 800, 600 },
})

-- Floating generic class
hl.window_rule({
  name   = "generic-float",
  match  = { class = "^(local\\.floating)$" },
  float  = true,
  center = true,
  size   = { 800, 600 },
})

hl.window_rule({
  name   = "mv",
  match  = { initial_class = "^(imv|mpv|wiremix|impala)$" },
  float  = true,
  center = true,
  size   = { 600, 600 },
})

